#include "PluginEditor.h"

#include <FourierizerUIData.h>  // generated by juce_add_binary_data: the built UI (index.html)

namespace {
const char* kParamIds[] = {"attack", "decay", "sustain", "release", "root", "volume"};

// WebView2 needs a writable folder; by default it would use the host's (read-only) install folder.
juce::File webViewDataFolder() {
    return juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("Fourierizer-WebView2");
}

juce::var obj(std::initializer_list<std::pair<const char*, juce::var>> props) {
    auto* o = new juce::DynamicObject();
    for (auto& [k, v] : props) o->setProperty(k, v);
    return juce::var(o);
}

juce::String audioWildcard() { return "*.wav;*.aif;*.aiff;*.flac;*.mp3;*.ogg"; }
} // namespace

FourierizerEditor::FourierizerEditor(FourierizerProcessor& p)
    : AudioProcessorEditor(&p), proc_(p), web_(options()) {
    addAndMakeVisible(web_);
    web_.goToURL(juce::WebBrowserComponent::getResourceProviderRoot());
    for (auto* id : kParamIds) proc_.parameters.addParameterListener(id, this);
    proc_.engine.onProjectLoaded = [this] { web_.emitEventIfBrowserIsVisible("projectLoaded", juce::var()); };

    setResizable(true, true);
    // Open at the designed 1440×900 when the screen allows it; the UI scales itself to any size.
    setResizeLimits(800, 500, 4000, 2500);
    auto area = juce::Rectangle<int>(1440, 900);
    if (const auto* display = juce::Desktop::getInstance().getDisplays().getPrimaryDisplay())
        area = area.getIntersection(display->userBounds.toNearestInt().reduced(40).withZeroOrigin());
    const double scale = std::min(area.getWidth() / 1440.0, area.getHeight() / 900.0);
    setSize(juce::roundToInt(1440 * scale), juce::roundToInt(900 * scale));
    startTimerHz(30);
}

FourierizerEditor::~FourierizerEditor() {
    stopTimer();
    proc_.engine.onProjectLoaded = nullptr;
    for (auto* id : kParamIds) proc_.parameters.removeParameterListener(id, this);
    masterReference.clear();
}

void FourierizerEditor::resized() { web_.setBounds(getLocalBounds()); }

fzp::Done FourierizerEditor::later(Completion complete) {
    juce::WeakReference<FourierizerEditor> self(this);
    return [self, complete](juce::var result) {
        juce::MessageManager::callAsync([self, complete, result] {
            if (self != nullptr) complete(result);
        });
    };
}

juce::WebBrowserComponent::Options FourierizerEditor::options() {
    using O = juce::WebBrowserComponent::Options;
    auto& engine = proc_.engine;
    auto& sampler = proc_.sampler;
    auto base = O{};
#if JUCE_WINDOWS
    base = base.withBackend(O::Backend::webview2)
               .withWinWebView2Options(O::WinWebView2{}.withUserDataFolder(webViewDataFolder()).withBackgroundColour(juce::Colour(0xffe4e7ea)));
#endif
    return base
        .withNativeIntegrationEnabled()
        .withKeepPageLoadedWhenBrowserIsHidden()
        .withResourceProvider([this](const auto& url) { return resource(url); })
        .withNativeFunction("hello", [this](Args, Completion done) {
            done(obj({{"host", juce::PluginHostType().getHostDescription()},
                      {"version", JucePlugin_VersionString},
                      {"standalone", proc_.wrapperType == juce::AudioProcessor::wrapperType_Standalone}}));
        })
        .withNativeFunction("loadProject", [this](Args, Completion done) { loadProject(std::move(done)); })
        .withNativeFunction("saveProject", [&engine](Args a, Completion done) {
            engine.setProject(a[0].toString());
            done(true);
        })
        .withNativeFunction("uploadBegin", [this](Args, Completion done) {
            const int id = nextUpload_++;
            uploads_[id];
            done(id);
        })
        .withNativeFunction("uploadChunk", [this](Args a, Completion done) {
            auto it = uploads_.find((int) a[0]);
            done(it != uploads_.end() && juce::Base64::convertFromBase64(it->second, a[1].toString()));
        })
        .withNativeFunction("uploadEnd", [this](Args a, Completion done) {
            auto it = uploads_.find((int) a[0]);
            if (it == uploads_.end()) return done(obj({{"error", "unknown upload"}}));
            juce::MemoryBlock bytes(it->second.getData(), it->second.getDataSize());
            uploads_.erase(it);
            proc_.engine.decodeBytes((int) a[1], std::move(bytes), a[2].toString(), later(std::move(done)));
        })
        .withNativeFunction("pickFile", [this](Args a, Completion done) { pickFile((int) a[0], std::move(done)); })
        .withNativeFunction("spectrogram", [this](Args a, Completion done) {
            try {
                proc_.engine.spectrogram((int) a[0], (double) a[1], fzp::Engine::gridOf(a[2]), later(std::move(done)));
            } catch (const std::exception& e) { done(obj({{"error", juce::String(e.what())}})); }
        })
        .withNativeFunction("render", [this](Args a, Completion done) { proc_.engine.render(a[0], later(std::move(done))); })
        .withNativeFunction("result", [&engine](Args, Completion done) { done(engine.resultInfo()); })
        .withNativeFunction("preview", [this](Args a, Completion done) { proc_.engine.preview(a[0], later(std::move(done))); })
        .withNativeFunction("stopPreview", [&sampler](Args, Completion done) { sampler.stopPreview(); done(true); })
        .withNativeFunction("noteOn", [&sampler](Args a, Completion done) { sampler.uiNoteOn((int) a[0], (float) (double) a[1]); done(true); })
        .withNativeFunction("noteOff", [&sampler](Args a, Completion done) { sampler.uiNoteOff((int) a[0]); done(true); })
        .withNativeFunction("allOff", [&sampler](Args, Completion done) { sampler.uiAllOff(); done(true); })
        .withNativeFunction("setParams", [this](Args a, Completion done) { proc_.setSamplerParams(a[0]); done(true); })
        .withNativeFunction("resultToLayer", [&engine](Args a, Completion done) { done(engine.resultToLayer((int) a[0], a[1].toString())); })
        .withNativeFunction("exportResult", [this](Args, Completion done) { exportResult(std::move(done)); })
        .withNativeFunction("dragResult", [this](Args, Completion done) { dragResult(); done(true); });
}

std::optional<juce::WebBrowserComponent::Resource> FourierizerEditor::resource(const juce::String& url) {
    auto path = url.upToFirstOccurrenceOf("?", false, false);
    if (path.startsWith("/data/")) {
        if (auto bytes = proc_.engine.blob(path.substring(6))) return juce::WebBrowserComponent::Resource{std::move(*bytes), "application/octet-stream"};
        return std::nullopt;
    }
    if (path.isEmpty() || path == "/" || path == "/index.html") {
        int size = 0;
        if (const auto* data = FourierizerUIData::getNamedResource("index_html", size)) {
            const auto* b = reinterpret_cast<const std::byte*>(data);
            return juce::WebBrowserComponent::Resource{std::vector<std::byte>(b, b + size), "text/html"};
        }
    }
    return std::nullopt;
}

void FourierizerEditor::loadProject(Completion done) {
    juce::Array<juce::var> layers;
    for (int i = 0; i < 4; ++i) layers.add(proc_.engine.sourceInfo(i));
    const auto project = proc_.engine.project();
    done(obj({{"project", project.isEmpty() ? juce::var() : juce::var(project)},
              {"layers", layers},
              {"result", proc_.engine.resultInfo()},
              {"params", proc_.samplerParams()}}));
}

void FourierizerEditor::pickFile(int layer, Completion done) {
    chooser_ = std::make_unique<juce::FileChooser>("Load a sound into layer " + juce::String(layer + 1), juce::File(), audioWildcard());
    auto complete = later(std::move(done));
    chooser_->launchAsync(juce::FileBrowserComponent::openMode | juce::FileBrowserComponent::canSelectFiles,
                          [this, layer, complete](const juce::FileChooser& fc) {
                              const auto file = fc.getResult();
                              if (file == juce::File()) return complete(juce::var());
                              proc_.engine.decodeFile(layer, file, complete);
                          });
}

void FourierizerEditor::exportResult(Completion done) {
    chooser_ = std::make_unique<juce::FileChooser>("Export the result", juce::File::getSpecialLocation(juce::File::userMusicDirectory).getChildFile("Fourierizer.wav"), "*.wav");
    auto complete = later(std::move(done));
    chooser_->launchAsync(juce::FileBrowserComponent::saveMode | juce::FileBrowserComponent::warnAboutOverwriting,
                          [this, complete](const juce::FileChooser& fc) {
                              auto file = fc.getResult();
                              if (file == juce::File()) return complete(juce::var());
                              file = file.withFileExtension(".wav");
                              const bool ok = proc_.engine.writeResultWav(file);
                              complete(ok ? juce::var(file.getFullPathName()) : obj({{"error", "could not write " + file.getFullPathName()}}));
                          });
}

void FourierizerEditor::dragResult() {
    const auto file = proc_.engine.resultWavFile();
    if (!file.existsAsFile()) return;
    // The OS drag starts while the mouse button is still down over the WebView.
    performExternalDragDropOfFiles({file.getFullPathName()}, false, this);
}

void FourierizerEditor::timerCallback() {
    auto& s = proc_.sampler;
    const float r = s.resultPosition(), p = s.previewPosition();
    const int layer = s.previewLayer(), voices = s.activeVoices();
    if (r != lastPlay_.result || p != lastPlay_.preview || layer != lastPlay_.layer || voices != lastPlay_.voices) {
        lastPlay_ = {r, p, layer, voices};
        web_.emitEventIfBrowserIsVisible("play", obj({{"result", r}, {"preview", layer}, {"previewPos", p}, {"voices", voices}}));
    }
    if (paramsDirty_.exchange(false)) web_.emitEventIfBrowserIsVisible("params", proc_.samplerParams());
}
